Key Event Listeners: Keys
def on_key_down(key):
    if key == keys.UP:
        print("Up key was pressed")
    elif key == keys.DOWN:
        print("Down key was pressed")

def on_key_up(key):
    if key == keys.UP:
        print("Up key was released")
    elif key == keys.DOWN:
        print("Down key was released")
